func TestEnumEksClusterMatchedBy(t *testing.T) {
	t.Run("NewFromString_name", func(t *testing.T) {
		t.Parallel()
		val, err := NewEksClusterMatchedByFromString("name")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, EksClusterMatchedBy("name"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_nodes", func(t *testing.T) {
		t.Parallel()
		val, err := NewEksClusterMatchedByFromString("nodes")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, EksClusterMatchedBy("nodes"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewEksClusterMatchedByFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewEksClusterMatchedByFromString("name")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

